#include <immintrin.h>
extern "C" __m512d _ZGVeN8v_exp(__m512d);
__attribute__((target("avx512f,avx512dq,fma"),always_inline)) static inline __m512d sigv16(__m512d x){const __m512d one=_mm512_set1_pd(1.0),zero=_mm512_setzero_pd();return _mm512_div_pd(one,_mm512_add_pd(one,_ZGVeN8v_exp(_mm512_sub_pd(zero,x))));}
__attribute__((target("avx512f,avx512dq,fma"))) static void slice16(const Data&d,size_t b,size_t e,const vector<double>&p,array<double,P>&g,long double&ss,long double&ps){
 const double*w2=&p[IN*H];const __m512d w20=_mm512_loadu_pd(w2),w21=_mm512_loadu_pd(w2+8),one=_mm512_set1_pd(1.0);__m512d g20=_mm512_setzero_pd(),g21=_mm512_setzero_pd(),g10[IN],g11[IN];for(int k=0;k<IN;k++){g10[k]=_mm512_setzero_pd();g11[k]=_mm512_setzero_pd();}size_t r=b;
 for(;r+8<=e;r+=8){const double*x[8];__m512d z0[8],z1[8];for(int q=0;q<8;q++){x[q]=&d.x[(r+q)*IN];z0[q]=_mm512_setzero_pd();z1[q]=_mm512_setzero_pd();}for(int k=0;k<IN;k++){const __m512d wa=_mm512_loadu_pd(&p[k*H]),wb=_mm512_loadu_pd(&p[k*H+8]);for(int q=0;q<8;q++){const __m512d xv=_mm512_set1_pd(x[q][k]);z0[q]=_mm512_fmadd_pd(xv,wa,z0[q]);z1[q]=_mm512_fmadd_pd(xv,wb,z1[q]);}}__m512d h0[8],h1[8];double d3[8];for(int q=0;q<8;q++){h0[q]=sigv16(z0[q]);h1[q]=sigv16(z1[q]);const double raw=_mm512_reduce_add_pd(_mm512_add_pd(_mm512_mul_pd(h0[q],w20),_mm512_mul_pd(h1[q],w21))),o=sig(raw),er=o-d.y[r+q];d3[q]=er*o*(1-o);ss+=er*er;ps+=abs(er/d.y[r+q])*100.0;}for(int q=0;q<8;q++){const __m512d dv=_mm512_set1_pd(d3[q]);g20=_mm512_fmadd_pd(h0[q],dv,g20);g21=_mm512_fmadd_pd(h1[q],dv,g21);const __m512d d20=_mm512_mul_pd(_mm512_mul_pd(dv,w20),_mm512_mul_pd(h0[q],_mm512_sub_pd(one,h0[q]))),d21=_mm512_mul_pd(_mm512_mul_pd(dv,w21),_mm512_mul_pd(h1[q],_mm512_sub_pd(one,h1[q])));for(int k=0;k<IN;k++){const __m512d xv=_mm512_set1_pd(x[q][k]);g10[k]=_mm512_fmadd_pd(xv,d20,g10[k]);g11[k]=_mm512_fmadd_pd(xv,d21,g11[k]);}}}
 for(;r<e;r++){const double*x=&d.x[r*IN];__m512d z0=_mm512_setzero_pd(),z1=_mm512_setzero_pd();for(int k=0;k<IN;k++){const __m512d xv=_mm512_set1_pd(x[k]);z0=_mm512_fmadd_pd(xv,_mm512_loadu_pd(&p[k*H]),z0);z1=_mm512_fmadd_pd(xv,_mm512_loadu_pd(&p[k*H+8]),z1);}const __m512d h0=sigv16(z0),h1=sigv16(z1);const double raw=_mm512_reduce_add_pd(_mm512_add_pd(_mm512_mul_pd(h0,w20),_mm512_mul_pd(h1,w21))),o=sig(raw),er=o-d.y[r],d3=er*o*(1-o);ss+=er*er;ps+=abs(er/d.y[r])*100.0;const __m512d dv=_mm512_set1_pd(d3);g20=_mm512_fmadd_pd(h0,dv,g20);g21=_mm512_fmadd_pd(h1,dv,g21);const __m512d d20=_mm512_mul_pd(_mm512_mul_pd(dv,w20),_mm512_mul_pd(h0,_mm512_sub_pd(one,h0))),d21=_mm512_mul_pd(_mm512_mul_pd(dv,w21),_mm512_mul_pd(h1,_mm512_sub_pd(one,h1)));for(int k=0;k<IN;k++){const __m512d xv=_mm512_set1_pd(x[k]);g10[k]=_mm512_fmadd_pd(xv,d20,g10[k]);g11[k]=_mm512_fmadd_pd(xv,d21,g11[k]);}}
 _mm512_storeu_pd(&g[IN*H],g20);_mm512_storeu_pd(&g[IN*H+8],g21);for(int k=0;k<IN;k++){_mm512_storeu_pd(&g[k*H],g10[k]);_mm512_storeu_pd(&g[k*H+8],g11[k]);}}
static E eval16(const Data&d,const vector<double>&p,int threads){E e;e.g.assign(P,0);vector<array<double,P>>gs(threads);vector<long double>ss(threads),ps(threads);
#pragma omp parallel num_threads(threads)
 {const int tid=omp_get_thread_num();const size_t base=d.n/threads,rem=d.n%threads,b=tid*base+min<size_t>(tid,rem),cnt=base+(tid<(int)rem);slice16(d,b,b+cnt,p,gs[tid],ss[tid],ps[tid]);}
 long double ssum=0,psum=0;for(int t=0;t<threads;t++){ssum+=ss[t];psum+=ps[t];for(int i=0;i<P;i++)e.g[i]+=gs[t][i];}const double inv=1.0/d.n;e.f=.5*(double)ssum*inv;e.pe=(double)psum*inv;for(double&v:e.g)v*=inv;return e;}
static R run16(const Data&d,bool simd){vector<double>p=init();deque<Pair>hist;const auto st=chrono::steady_clock::now();E cur=simd?eval16(d,p,4):eval_exact(d,p,4);int ev=1;for(int it=0;it<20&&cur.pe>3.9;it++){vector<double>q=cur.g,alpha(hist.size());for(size_t ii=hist.size();ii>0;--ii){const size_t i=ii-1;alpha[i]=hist[i].rho*dot(hist[i].s,q);for(int k=0;k<P;k++)q[k]-=alpha[i]*hist[i].y[k];}double gamma=1;if(!hist.empty()){auto&h=hist.back();const double yy=dot(h.y,h.y);if(yy>0)gamma=dot(h.s,h.y)/yy;}vector<double>r=q;for(double&v:r)v*=gamma;for(size_t i=0;i<hist.size();i++){const double beta=hist[i].rho*dot(hist[i].y,r);for(int k=0;k<P;k++)r[k]+=hist[i].s[k]*(alpha[i]-beta);}for(double&v:r)v=-v;double gd=dot(cur.g,r);if(gd>=0){r=cur.g;for(double&v:r)v=-v;gd=-dot(cur.g,cur.g);hist.clear();}double step=1;vector<double>pn(P);E ne;bool accepted=false;for(int ls=0;ls<20;ls++){for(int k=0;k<P;k++)pn[k]=p[k]+step*r[k];ne=simd?eval16(d,pn,4):eval_exact(d,pn,4);ev++;if(ne.f<=cur.f+1e-4*step*gd){accepted=true;break;}step*=.5;}if(!accepted)break;vector<double>s(P),y(P);for(int k=0;k<P;k++){s[k]=pn[k]-p[k];y[k]=ne.g[k]-cur.g[k];}const double sy=dot(s,y);if(sy>1e-12){if(hist.size()==10)hist.pop_front();hist.push_back(Pair{s,y,1/sy});}p.swap(pn);cur=ne;}return {chrono::duration<double>(chrono::steady_clock::now()-st).count(),cur.pe,ev,0};}
int main(int argc,char**argv){const size_t n=argc>1?strtoull(argv[1],nullptr,10):1000000;const int reps=argc>2?atoi(argv[2]):7;Data d(n);fill(d);cout<<setprecision(17);for(int rep=0;rep<reps;rep++){R v15,v16;if(rep%2==0){v15=run16(d,false);v16=run16(d,true);}else{v16=run16(d,true);v15=run16(d,false);}cout<<n<<','<<rep<<','<<v15.sec<<','<<v16.sec<<','<<v15.pe<<','<<v16.pe<<','<<v15.exact_evals<<','<<v16.exact_evals<<'\n';}return 0;}
